use xiom.io;

use xiom.string;
fn calculate(expr: Str) -> Result[Int, Str] {
  if string.str_len(expr) == 0 {
    return Err("Expression is empty");
  }

  let space1 = 0;
  let space2 = 0;
  let i = 0;
  while i < string.str_len(expr) {
    let ch = string.str_slice(expr, i, i + 1);
    if ch == " " && space1 == 0 {
      space1 = i;
    } elif ch == " " && space1 != 0 && space2 == 0 {
      space2 = i;
    }
    i = i + 1;
  }

  if space1 == 0 || space2 == 0 {
    return Err("Format: OPERATOR A B");
  }

  let op = string.str_slice(expr, 0, space1);
  let a_str = string.str_slice(expr, space1 + 1, space2);
  let b_str = string.str_slice(expr, space2 + 1, string.str_len(expr));

  let a = string.str_to_int(a_str)?;
  let b = string.str_to_int(b_str)?;

  if op == "ADD" { return Ok(a + b); }
  elif op == "SUB" { return Ok(a - b); }
  elif op == "MUL" { return Ok(a * b); }
  elif op == "DIV" {
    if b == 0 { return Err("Division by zero"); }
    return Ok(a / b);
  }
  else { return Err("Unknown operator: " + op); }
}

fn main() -> Int {
  match calculate("ADD 5 3") {
    Ok(r) => { io.println(string.int_to_str(r)); return r; }
    Err(e) => { io.println(e.to_str()); return -1; }
  }
}
